#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node *prev;
    struct Node *next;
} Node;

static Node *where[100001];

static void detach(Node *node) {
    node->prev->next = node->next;
    node->next->prev = node->prev;
}

static void attach_front(Node *list, Node *node) {
    node->prev = list;
    node->next = list->next;
    list->next->prev = node;
    list->next = node;
}

int main(void) {
    int capacity, m;
    if (scanf("%d %d", &capacity, &m) != 2 || capacity < 1) {
        return 0;
    }
    Node list = {0, &list, &list};
    int size = 0, hits = 0, misses = 0;
    for (int i = 0; i < m; i++) {
        int key;
        if (scanf("%d", &key) != 1 || key < 0 || key > 100000) {
            break;
        }
        if (where[key] != NULL) {
            hits++;
            detach(where[key]);
            attach_front(&list, where[key]);
            continue;
        }
        misses++;
        if (size == capacity) {
            Node *oldest = list.prev;
            detach(oldest);
            where[oldest->key] = NULL;
            free(oldest);
            size--;
        }
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            return 1;
        }
        node->key = key;
        attach_front(&list, node);
        where[key] = node;
        size++;
    }
    printf("попаданий %d, промахов %d\n", hits, misses);
    for (Node *p = list.next; p != &list; p = p->next) {
        printf(p->next != &list ? "%d " : "%d\n", p->key);
    }
    while (list.next != &list) {
        Node *node = list.next;
        detach(node);
        free(node);
    }
    return 0;
}

